define('SAKHTSAR_VERSION', '2.5.0');
function sakhtsar_setup(){add_theme_support('title-tag');add_theme_support('post-thumbnails');add_theme_support('html5',array('search-form','comment-form','comment-list','gallery','caption','style','script'));add_theme_support('custom-logo',array('height'=>80,'width'=>180,'flex-height'=>true,'flex-width'=>true));register_nav_menus(array('primary'=>'منوی اصلی','footer_quick'=>'فوتر — دسترسی سریع','footer_about'=>'فوتر — درباره سخت‌سر'));}
add_action('after_setup_theme','sakhtsar_setup');
function sakhtsar_assets(){wp_enqueue_style('sakhtsar-style',get_stylesheet_uri(),array(),SAKHTSAR_VERSION);wp_enqueue_style('sakhtsar-rtl-overrides',get_template_directory_uri().'/assets/css/rtl-overrides.css',array('sakhtsar-style'),SAKHTSAR_VERSION);wp_enqueue_style('sakhtsar-footer-reference',get_template_directory_uri().'/assets/css/footer-reference.css',array('sakhtsar-style','sakhtsar-rtl-overrides'),SAKHTSAR_VERSION);wp_add_inline_style('sakhtsar-footer-reference',':root{--sakhtsar-social-size:'.max(12,min(64,absint(sakhtsar_get('social_icon_size',24)))).'px;}');if(get_query_var('sakhtsar_profile'))wp_enqueue_style('sakhtsar-profile',get_template_directory_uri().'/assets/css/profile.css',array('sakhtsar-style','sakhtsar-rtl-overrides'),SAKHTSAR_VERSION);wp_enqueue_script('sakhtsar-main',get_template_directory_uri().'/assets/js/main.js',array(),SAKHTSAR_VERSION,true);}
add_action('wp_enqueue_scripts','sakhtsar_assets');
function sakhtsar_register_content(){$types=array('place'=>array('جاهای رامسر','جای رامسر','dashicons-location-alt','places'),'trip'=>array('مسیرهای گردشگری','مسیر گردشگری','dashicons-location','trips'),'event'=>array('رویدادها','رویداد','dashicons-calendar-alt','events'),'magazine'=>array('مجله سخت‌سر','مقاله مجله','dashicons-edit','magazine'),'gallery_item'=>array('گالری','تصویر گالری','dashicons-format-gallery','gallery'));foreach($types as $slug=>$data)register_post_type($slug,array('labels'=>array('name'=>$data[0],'singular_name'=>$data[1],'add_new'=>'افزودن جدید','add_new_item'=>'افزودن '.$data[1],'edit_item'=>'ویرایش '.$data[1],'new_item'=>'جدید','view_item'=>'مشاهده','search_items'=>'جستجو','not_found'=>'موردی پیدا نشد','menu_name'=>$data[0]),'public'=>true,'show_in_rest'=>true,'menu_icon'=>$data[2],'rewrite'=>array('slug'=>$data[3]),'has_archive'=>true,'supports'=>array('title','editor','thumbnail','excerpt','revisions','author')));register_taxonomy('place_type','place',array('labels'=>array('name'=>'دسته‌بندی مکان','singular_name'=>'دسته مکان'),'public'=>true,'show_in_rest'=>true,'hierarchical'=>true,'rewrite'=>array('slug'=>'place-type')));register_taxonomy('trip_type','trip',array('labels'=>array('name'=>'نوع مسیر','singular_name'=>'نوع مسیر'),'public'=>true,'show_in_rest'=>true,'hierarchical'=>true,'rewrite'=>array('slug'=>'trip-type')));register_taxonomy('event_type','event',array('labels'=>array('name'=>'نوع رویداد','singular_name'=>'نوع رویداد'),'public'=>true,'show_in_rest'=>true,'hierarchical'=>true,'rewrite'=>array('slug'=>'event-type')));register_taxonomy('magazine_category','magazine',array('labels'=>array('name'=>'دسته‌بندی مجله','singular_name'=>'دسته مجله'),'public'=>true,'show_in_rest'=>true,'hierarchical'=>true,'rewrite'=>array('slug'=>'magazine-category')));}
add_action('init','sakhtsar_register_content');
function sakhtsar_profile_route(){add_rewrite_rule('^profile/?$','index.php?sakhtsar_profile=1','top');add_rewrite_tag('%sakhtsar_profile%','([01])');} add_action('init','sakhtsar_profile_route',1);
function sakhtsar_profile_template($template){if(get_query_var('sakhtsar_profile')){$profile=get_template_directory().'/profile.php';if(file_exists($profile))return $profile;}return $template;} add_filter('template_include','sakhtsar_profile_template');
function sakhtsar_meta_boxes(){add_meta_box('sakhtsar_place_details','جزئیات مکان','sakhtsar_place_box','place','normal','high');add_meta_box('sakhtsar_trip_details','جزئیات مسیر','sakhtsar_trip_box','trip','normal','high');add_meta_box('sakhtsar_event_details','جزئیات رویداد','sakhtsar_event_box','event','normal','high');add_meta_box('sakhtsar_gallery_details','جزئیات گالری','sakhtsar_gallery_box','gallery_item','normal','high');} add_action('add_meta_boxes','sakhtsar_meta_boxes');
function sakhtsar_meta_input($key,$label,$value,$type='text'){printf('<p><label><strong>%s</strong></label><br><input class="widefat" type="%s" name="%s" value="%s"></p>',esc_html($label),esc_attr($type),esc_attr($key),esc_attr($value));}
function sakhtsar_place_box($post){wp_nonce_field('sakhtsar_meta','sakhtsar_meta_nonce');sakhtsar_meta_input('sakhtsar_address','آدرس',get_post_meta($post->ID,'sakhtsar_address',true));sakhtsar_meta_input('sakhtsar_rating','امتیاز',get_post_meta($post->ID,'sakhtsar_rating',true));sakhtsar_meta_input('sakhtsar_lat','عرض جغرافیایی',get_post_meta($post->ID,'sakhtsar_lat',true));sakhtsar_meta_input('sakhtsar_lng','طول جغرافیایی',get_post_meta($post->ID,'sakhtsar_lng',true));}
function sakhtsar_trip_box($post){wp_nonce_field('sakhtsar_meta','sakhtsar_meta_nonce');sakhtsar_meta_input('sakhtsar_duration','مدت مسیر',get_post_meta($post->ID,'sakhtsar_duration',true));sakhtsar_meta_input('sakhtsar_distance','مسافت',get_post_meta($post->ID,'sakhtsar_distance',true));sakhtsar_meta_input('sakhtsar_stops','تعداد توقف‌ها',get_post_meta($post->ID,'sakhtsar_stops',true));sakhtsar_meta_input('sakhtsar_difficulty','سطح مسیر',get_post_meta($post->ID,'sakhtsar_difficulty',true));}
function sakhtsar_event_box($post){wp_nonce_field('sakhtsar_meta','sakhtsar_meta_nonce');sakhtsar_meta_input('sakhtsar_event_date','تاریخ رویداد',get_post_meta($post->ID,'sakhtsar_event_date',true),'date');sakhtsar_meta_input('sakhtsar_event_time','ساعت',get_post_meta($post->ID,'sakhtsar_event_time',true),'time');sakhtsar_meta_input('sakhtsar_event_location','محل برگزاری',get_post_meta($post->ID,'sakhtsar_event_location',true));}
function sakhtsar_gallery_box($post){wp_nonce_field('sakhtsar_meta','sakhtsar_meta_nonce');sakhtsar_meta_input('sakhtsar_gallery_credit','اعتبار تصویر',get_post_meta($post->ID,'sakhtsar_gallery_credit',true));}
function sakhtsar_save_meta($post_id){if(!isset($_POST['sakhtsar_meta_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['sakhtsar_meta_nonce'])),'sakhtsar_meta'))return;if(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)return;if(!current_user_can('edit_post',$post_id))return;$keys=array('sakhtsar_address','sakhtsar_rating','sakhtsar_lat','sakhtsar_lng','sakhtsar_duration','sakhtsar_distance','sakhtsar_stops','sakhtsar_difficulty','sakhtsar_event_date','sakhtsar_event_time','sakhtsar_event_location','sakhtsar_gallery_credit');foreach($keys as $key)if(isset($_POST[$key]))update_post_meta($post_id,$key,sanitize_text_field(wp_unslash($_POST[$key])));} add_action('save_post','sakhtsar_save_meta');
