$wp_customize->add_section('sakhtsar_profile',array('title'=>'سخت‌سر | پروفایل کاربری','description'=>'تمام تنظیمات ظاهری و متن‌های صفحه پروفایل','priority'=>26));
$profile_fields=array('profile_title'=>array('عنوان بنر','پروفایل کاربری','text','sanitize_text_field'),'profile_breadcrumb'=>array('متن مسیر صفحه','خانه  ‹  پروفایل کاربری','text','sanitize_text_field'),'profile_default_bio'=>array('معرفی پیش‌فرض','سلام! من عاشق سفر، طبیعت و کشف مکان‌های جدید هستم. همیشه سعی می‌کنم بهترین تجربه‌هایم را با دیگران به اشتراک بگذارم.','textarea','sanitize_textarea_field'),'profile_stat_trips'=>array('عنوان آمار مسیرها','مسیرهای سفر','text','sanitize_text_field'),'profile_stat_places'=>array('عنوان آمار مکان‌ها','جاذبه‌ها','text','sanitize_text_field'),'profile_stat_articles'=>array('عنوان آمار مقالات','مقالات','text','sanitize_text_field'),'profile_stat_events'=>array('عنوان آمار ویدیوها','ویدیوها','text','sanitize_text_field'),'profile_about_title'=>array('عنوان درباره من','درباره من','text','sanitize_text_field'),'profile_personal_title'=>array('عنوان اطلاعات شخصی','اطلاعات شخصی','text','sanitize_text_field'),'profile_favorites_title'=>array('عنوان علاقه‌مندی‌ها','علاقه‌مندی‌های من','text','sanitize_text_field'),'profile_history_title'=>array('عنوان تاریخچه','تاریخچه بازدیدها','text','sanitize_text_field'),'profile_comments_title'=>array('عنوان نظرات','آخرین نظرات من','text','sanitize_text_field'),'profile_badges_title'=>array('عنوان نشان‌ها','نشان‌ها و دستاوردها','text','sanitize_text_field'),'profile_trips_title'=>array('عنوان مسیرها','مسیرهای من','text','sanitize_text_field'),'badge_one'=>array('نشان اول','سفرهای زیاد','text','sanitize_text_field'),'badge_two'=>array('نشان دوم','کشف‌گر طبیعت','text','sanitize_text_field'),'badge_three'=>array('نشان سوم','عضو ویژه','text','sanitize_text_field'),'badge_four'=>array('نشان چهارم','نویسنده برتر','text','sanitize_text_field'),'badge_one_desc'=>array('توضیح نشان اول','۱۰ سفر','text','sanitize_text_field'),'badge_two_desc'=>array('توضیح نشان دوم','۲۰ جاذبه','text','sanitize_text_field'),'badge_three_desc'=>array('توضیح نشان سوم','۱ سال','text','sanitize_text_field'),'badge_four_desc'=>arr