function sakhtsar_profile_user_fields($user){if(!current_user_can('edit_users')&&get_current_user_id()!=$user->ID)return;wp_nonce_field('sakhtsar_user_profile','sakhtsar_user_profile_nonce');?><h2>سخت‌سر — اطلاعات پروفایل</h2><table class="form-table"><tr><th><label for="sakhtsar_phone">شماره موبایل</label></th><td><input class="regular-text" name="sakhtsar_phone" id="sakhtsar_phone" value="<?php echo esc_attr(get_user_meta($user->ID,'sakhtsar_phone',true));?>"></td></tr><tr><th><label for="sakhtsar_location">محل زندگی</label></th><td><input class="regular-text" name="sakhtsar_location" id="sakhtsar_location" value="<?php echo esc_attr(get_user_meta($user->ID,'sakhtsar_location',true));?>"></td></tr><tr><th><label for="sakhtsar_birthdate">تاریخ تولد</label></th><td><input class="regular-text" name="sakhtsar_birthdate" id="sakhtsar_birthdate" value="<?php echo esc_attr(get_user_meta($user->ID,'sakhtsar_birthdate',true));?>" placeholder="مثلاً 1388/01/20"></td></tr><tr><th><label for="sakhtsar_favorite_places">شناسه مکان‌های علاقه‌مندی</label></th><td><input class="regular-text" name="sakhtsar_favorite_places" id="sakhtsar_favorite_places" value="<?php echo esc_attr(get_user_meta($user->ID,'sakhtsar_favorite_places',true));?>"><p class="description">شناسه پست‌ها را با کاما جدا کن؛ مثال: 12,45,78</p></td></tr></table><?php }
add_action('show_user_profile','sakhtsar_profile_user_fields');add_action('edit_user_profile','sakhtsar_profile_user_fields');
function sakhtsar_save_profile_user_fields($user_id){if(!isset($_POST['sakhtsar_user_profile_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['sakhtsar_user_profile_nonce'])),'sakhtsar_user_profile'))return;if(!current_user_can('edit_user',$user_id))return;foreach(array('sakhtsar_phone','sakhtsar_location','sakhtsar_birthdate','sakhtsar_favorite_places') as $key)if(isset($_POST[$key]))update_user_meta($user_id,$key,sanitize_text_field(wp_unslash($_POST[$key])));}
add_action('personal_options_update','sakhtsar_save_profile_user_fields');add_action('edit_user_profile_update','sakhtsar_save_profile_user_fields');
function sakhtsar_get($key,$fallback=''){return get_theme_mod('sakhtsar_'.$key,$fallback);} function sakhtsar_img($url){return esc_url($url);} function sakhtsar_featured_image($post_id,$fallback=''){$url=get_the_post_thumbnail_url($post_id,'large');return $url?:$fallback;}
function sakhtsar_footer_socials(){$socials=array('instagram'=>array('اینستاگرام','◎'),'telegram'=>array('تلگرام','➤'),'youtube'=>array('یوتیوب','▶'),'aparat'=>array('آپارات','◈'),'social5'=>array('شبکه اجتماعی','⊕'));foreach($socials as $id=>$data){$url=sakhtsar_get('social_'.$id.'_url','#');$icon=sakhtsar_get('social_'.$id.'_icon','');echo '<a href="'.esc_url($url).'" aria-label="'.esc_attr($data[0]).'" title="'.esc_attr($data[0]).'">';if($icon)echo '<img src="'.esc_url($icon).'" alt="" aria-hidden="true">';else echo '<span>'.esc_html($data[1]).'</span>';echo '</a>';}}
function sakhtsar_flush_rewrites(){if(get_option('sakhtsar_rewrite_version')!=='2.5.0'){flush_rewrite_rules(false);update_option('sakhtsar_rewrite_version','2.5.0');}} add_action('init','sakhtsar_flush_rewrites',99);
